+          `--${boundary}\r\n` +
+            `Content-Disposition: form-data; name="${name}"; filename="${filename}"\r\n` +
+            `Content-Type: ${mimeType}\r\n` +
+            `\r\n`,
+        );
+        bb.write(buffer);
+        bb.write('\r\n');
+      }
