+function spawnExternalCommand(command, args) {
+	const spawn = require("cross-spawn");
+	const result = spawn.sync(command, args, {
+		encoding: "utf8",
+		stdio: "inherit",
+	});
+
+	if (result.error) {
+		throw result.error;
+	}
+
+	if (result.signal) {
+		process.kill(process.pid, result.signal);
+		return;
+	}
+
+	process.exitCode = result.status ?? 0;
+}
