+      Self {
+        stdin_mode: windows_console_mode::get(
+          winapi::um::winbase::STD_INPUT_HANDLE,
+        ),
+        stdout_mode: windows_console_mode::get(
+          winapi::um::winbase::STD_OUTPUT_HANDLE,
+        ),
